let rollTotals = [], accum = 0, discardedStr = '';

for (let i = 0; i < 6; i++) {
   let roll;
   do { roll = await new Roll('3d6').evaluate(); } while (roll.total < 6);
   accum += roll.total;
   rollTotals.push(roll.total);
   discardedStr += `Roll ${i + 1}: ${roll.total}<br>`;
}

const content = `<h3>Rolling Ability Scores</h3><p>Method: 3d6</p>${discardedStr}
<strong>Average:</strong> ${(accum / 6).toFixed(2)}<br>
<button class="apply-scores">Apply to Selected</button>`;

const chatMessage = await ChatMessage.create({ content, flavor: 'Ability Score Rolls' });

Hooks.once('renderChatMessage', (message, html) => {
   if (message.id !== chatMessage.id) return;
   const btn = html.find('.apply-scores');

   btn.click(async () => {
      const actor = canvas.tokens.controlled[0]?.actor;
      if (!actor) return ui.notifications.warn("Please select an actor.");

      const updates = Object.keys(actor.system.abilities)
         .slice(0, 6)
         .reduce((acc, key, i) => ({ ...acc, [`system.abilities.${key}.value`]: rollTotals[i] }), {});

      await actor.update(updates);
      ui.notifications.info(`Applied scores to ${actor.name}!`);
   });

   setTimeout(() => btn.prop('disabled', true).text('Expired'), 60000);
});
